pub fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    if n <= 1 {
        return numbers;
    }

    // Result length is 2*n - 1: elements at even indices come from input,
    // elements at odd indices are the delimiter.
    let mut result = Vec::with_capacity(2 * n - 1);

    for (i, &x) in numbers.iter().enumerate() {
        if i > 0 {
            result.push(delimiter);
        }
        result.push(x);
    }

    result
}